exec(open('/app/load.py').read())
import sys
by_pat=collections.defaultdict(list)
for t,items in res.items():
    if t in ('Patient','Basic'): continue
    for r in items:
        p=subj(r)
        if p: by_pat[p].append(r)
spec_by_id={s['id']:s for s in res['Specimen']}
basic_by_acc=collections.defaultdict(list)
for b in res['Basic']:
    basic_by_acc[ext(b,'accession')].append(b)
pat_by_id={p['id']:p for p in res['Patient']}
pat_by_mrn={}
for p in res['Patient']:
    pat_by_mrn[p['identifier'][0]['value']]=p

def et(r): return ext(r,'event-time') or ''
def line(r):
    t=r['resourceType']; i=r['id']
    if t=='EpisodeOfCare':
        return f"EPISODE {i} start={r['period']['start']} status={r['status']} type={r['type'][0]['text']}"
    if t=='Condition':
        return f"[{et(r)}] Condition {i}: {r['code']['text']} recorder={r.get('recorder',{}).get('display')}"
    if t=='Observation':
        sp=r.get('specimen',{}).get('reference','').split('/')[-1]
        s=spec_by_id.get(sp)
        acc=r.get('identifier',[{}])[0].get('value')
        out=f"[{et(r)}] Obs {i}: {r['code']['text']} coll={r.get('effectiveDateTime')} issued={r.get('issued')} status={r['status']} val={r.get('valueString')!r} acc={acc}"
        nt=' | '.join(n['text'] for n in r.get('note',[]))
        if nt: out+=f" NOTE:{nt}"
        if s:
            out+=f"\n     Spec {s['id']} acc={s.get('accessionIdentifier',{}).get('value')} coll={s.get('collection',{}).get('collectedDateTime')} by={s.get('collection',{}).get('collector',{}).get('display')} label=({ext(s,'label-name')}|{ext(s,'label-mrn')}|{ext(s,'label-dob')}) subj={subj(s)}"
        for b in basic_by_acc.get(acc,[]):
            out+=f"\n     Accn {b['id']} acc={ext(b,'accession')} ({ext(b,'patient-name')}|{ext(b,'patient-mrn')}|{ext(b,'patient-dob')}) recv={ext(b,'received')} by={b.get('author',{}).get('display')}"
        return out
    if t=='Specimen':
        return None
    if t=='MedicationAdministration':
        nt=' | '.join(n['text'] for n in r.get('note',[]))
        return f"[{et(r)}] MedAdmin {i}: {r['medicationCodeableConcept']['text']} {r.get('dosage',{}).get('text')} status={r['status']} eff={r.get('effectiveDateTime')} perf={[p['actor']['display'] for p in r.get('performer',[])]} NOTE:{nt}"
    if t=='MedicationDispense':
        nt=' | '.join(n['text'] for n in r.get('note',[]))
        return f"[{et(r)}] MedDisp {i}: {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} handed={r.get('whenHandedOver')} sig={[d['text'] for d in r.get('dosageInstruction',[])]} NOTE:{nt}"
    if t=='AllergyIntolerance':
        return f"[{et(r)}] Allergy {i}: {r['code']['text']} rx={[m['text'] for rr in r.get('reaction',[]) for m in rr['manifestation']]}"
    if t=='DocumentReference':
        return f"[{et(r)}] Doc {i} ({r['type']['text']}, {ext(r,'author-role')}, author={[a['display'] for a in r.get('author',[])]}, docStatus={r.get('docStatus')}):\n  \"\"\"{r['description']}\"\"\""
    if t=='Task':
        if r['status']=='requested':
            return f"[{r['authoredOn']}] REQUEST {i}: {r['code']['coding'][0]['code']} focus={r.get('focus',{}).get('reference')} desc={r['description']}"
        return f"ITEM {i}: {r.get('businessStatus')}"
    return f"{t} {i}"

pids=sys.argv[1:] if len(sys.argv)>1 else sorted(pat_by_id)
for pid in pids:
    p=pat_by_id[pid]
    print('='*100)
    print(f"PATIENT {pid} mrn={p['identifier'][0]['value']} dob={p['birthDate']} sex={p['gender']} name={p['name'][0]['text']}")
    rs=sorted(by_pat[pid],key=lambda r: (et(r) or r.get('period',{}).get('start','')))
    for r in rs:
        l=line(r)
        if l: print(l)
